-- 导出  表 hospital_booking.balance_log 结构
CREATE TABLE IF NOT EXISTS `balance_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户',
  `type` varchar(20) NOT NULL COMMENT 'recharge/order_pay/order_refund',
  `amount_fen` bigint NOT NULL COMMENT '变动金额（单位：分），充值为正，支付为负',
  `balance_after_fen` bigint NOT NULL COMMENT '变动后余额（单位：分）',
  `order_id` bigint DEFAULT NULL COMMENT '关联预约 ID',
  `pay_method` varchar(20) DEFAULT NULL COMMENT 'wechat/alipay/balance',
  `remark` varchar(100) DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_balance_user_time` (`user_id`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='余额流水';

