-- 导出  表 hospital_booking.doctor 结构
CREATE TABLE IF NOT EXISTS `doctor` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `department_id` bigint NOT NULL COMMENT '所属科室',
  `name` varchar(50) NOT NULL COMMENT '姓名',
  `title` varchar(50) DEFAULT NULL COMMENT '职称',
  `gender` tinyint NOT NULL DEFAULT '1' COMMENT '1男 2女 0未知',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像路径',
  `intro` varchar(1000) DEFAULT NULL COMMENT '简介',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '0停用 1启用',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除。2026年9月19日01:12:39新增加',
  `create_time` datetime NOT NULL DEFAULT (now()) COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  `create_user` int DEFAULT NULL COMMENT '创建者的id',
  `update_user` int DEFAULT NULL COMMENT '最后更新者的id',
  PRIMARY KEY (`id`),
  KEY `idx_doctor_dept` (`department_id`),
  KEY `idx_doctor_status` (`status`),
  KEY `idx_doctor_deleted` (`deleted`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='医生表';

