-- 导出  表 hospital_booking.medicine 结构
CREATE TABLE IF NOT EXISTS `medicine` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL COMMENT '药品名称',
  `spec` varchar(100) DEFAULT NULL COMMENT '规格',
  `unit` varchar(20) NOT NULL DEFAULT '盒' COMMENT '单位',
  `price_fen` bigint NOT NULL DEFAULT '0' COMMENT '单价（单位：分）',
  `stock` int NOT NULL DEFAULT '0' COMMENT '库存',
  `usage_desc` varchar(200) DEFAULT NULL COMMENT '用法说明',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_medicine_name` (`name`),
  KEY `idx_medicine_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='药品库';

