-- 导出  表 hospital_booking.patient 结构
CREATE TABLE IF NOT EXISTS `patient` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint NOT NULL COMMENT '归属账号',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '就诊人姓名',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '就诊人电话',
  `id_card` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '就诊人身份证号',
  `gender` tinyint NOT NULL DEFAULT '1' COMMENT '就诊性别：1男 2女',
  `birth_date` date DEFAULT NULL COMMENT '就诊人出生日期',
  `nation` tinyint NOT NULL DEFAULT '1' COMMENT '使用中国民族编号',
  `address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系地址',
  `marital` tinyint NOT NULL DEFAULT '0' COMMENT '婚否 1已婚 2未婚',
  `is_default` tinyint NOT NULL DEFAULT '0' COMMENT '是否默认就诊人 1是 0否',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `create_time` datetime NOT NULL DEFAULT (now()),
  `update_time` datetime NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_deleted` (`user_id`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='就诊人档案表\r\n一个账号可以同时拥有多个就诊人，并为他们预约就诊\r\n';

