-- 导出  表 hospital_booking.payment_notify_log 结构
CREATE TABLE IF NOT EXISTS `payment_notify_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `channel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MOCK/WECHAT',
  `notify_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PAY' COMMENT 'PAY 支付通知 / REFUND 退款通知',
  `out_trade_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商户支付单号',
  `out_refund_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商户退款单号（退款通知用）',
  `transaction_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '网关交易号',
  `raw_body` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '回调原始报文（务必原样保存，验签排障用）',
  `sign_verified` tinyint NOT NULL DEFAULT '0' COMMENT '验签是否通过：0否 1是',
  `process_result` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理结果：SUCCESS/DUP/REFUND/ERROR',
  `error_msg` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '异常信息',
  `create_time` datetime DEFAULT (now()),
  PRIMARY KEY (`id`),
  KEY `idx_notify_log_out_trade_no` (`out_trade_no`),
  KEY `idx_notify_log_out_refund_no` (`out_refund_no`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='支付/退款回调流水（原文留存）';

