-- 导出  表 hospital_booking.payment_order 结构
CREATE TABLE IF NOT EXISTS `payment_order` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `out_trade_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商户支付单号（网关约束：数字/字母/_/-/|/*，长6~32，全局唯一）',
  `biz_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型：APPOINTMENT/PRESCRIPTION/RECHARGE',
  `biz_id` bigint NOT NULL COMMENT '业务单id，同一业务单允许多个支付单',
  `user_id` bigint NOT NULL COMMENT '付款用户id',
  `amount_fen` bigint NOT NULL COMMENT '支付金额（单位：分）',
  `currency` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CNY' COMMENT '币种',
  `pay_method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '支付方式：wechat/alipay/balance',
  `channel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '支付通道：MOCK/WECHAT',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'CREATED/PAID/REFUNDING/REFUNDED/CLOSED/FAILED',
  `prepay_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '网关预支付id',
  `transaction_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '网关侧交易号',
  `payer_openid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'JSAPI必传：付款人openid',
  `description` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品描述，如 挂号费-张明华',
  `expire_time` datetime DEFAULT NULL COMMENT '支付单过期时间（与 app.appointment.unpaid-expire-minutes 同源）',
  `paid_time` datetime DEFAULT NULL COMMENT '支付完成时间',
  `close_time` datetime DEFAULT NULL COMMENT '关单时间',
  `create_time` datetime DEFAULT (now()),
  `update_time` datetime DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_payment_order_out_trade_no` (`out_trade_no`),
  KEY `idx_payment_order_biz` (`biz_type`,`biz_id`),
  KEY `idx_payment_order_user` (`user_id`),
  KEY `idx_payment_order_status_expire` (`status`,`expire_time`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='支付单（与业务表解耦，一个业务单可多次尝试）\r\npayment_order 只有 out_trade_no 唯一，biz_id 故意不唯一，加了唯一索引会导致"关单后重试支付"直接插入失败。';

