-- 导出  表 hospital_booking.refund_order 结构
CREATE TABLE IF NOT EXISTS `refund_order` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `out_refund_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商户退款单号，唯一',
  `out_trade_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原商户支付单号',
  `payment_order_id` bigint NOT NULL COMMENT 'payment_order.id',
  `user_id` bigint DEFAULT NULL COMMENT '收款用户id',
  `amount_fen` bigint NOT NULL COMMENT '退款金额（单位：分）',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PROCESSING/SUCCESS/FAILED/CLOSED',
  `reason` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '退款原因',
  `refund_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '网关侧退款单号',
  `success_time` datetime DEFAULT NULL,
  `create_time` datetime DEFAULT (now()),
  `update_time` datetime DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_refund_order_out_refund_no` (`out_refund_no`),
  KEY `idx_refund_order_out_trade_no` (`out_trade_no`),
  KEY `idx_refund_order_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='退款单';

-- 正在导出表  hospital_booking.refund_order 的数据：~0 rows (大约)
