-- 导出  表 hospital_booking.sys_menu 结构
CREATE TABLE IF NOT EXISTS `sys_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '父菜单，0为顶级',
  `name` varchar(50) NOT NULL COMMENT '菜单名称',
  `path` varchar(100) NOT NULL COMMENT '前端路由',
  `icon` varchar(50) DEFAULT NULL COMMENT '图标名（Element Plus Icons）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序值',
  `roles` varchar(100) NOT NULL DEFAULT 'ADMIN' COMMENT '历史字段：角色可见性已迁移到 sys_role_menu',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='菜单表';

