-- 导出  表 hospital_booking.sys_role_menu 结构
CREATE TABLE IF NOT EXISTS `sys_role_menu` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `role_code` varchar(30) NOT NULL COMMENT '对应 sys_role.code',
  `menu_id` bigint NOT NULL COMMENT '对应 sys_menu.id',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_role_menu` (`role_code`,`menu_id`),
  KEY `idx_rm_menu` (`menu_id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='角色-菜单可见性';

