-- 导出  表 hospital_booking.sys_user 结构
CREATE TABLE IF NOT EXISTS `sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `username` varchar(50) NOT NULL COMMENT '用户名',
  `password` varchar(100) NOT NULL COMMENT '密码（BCrypt）',
  `nickname` varchar(50) DEFAULT NULL COMMENT '昵称',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `gender` tinyint NOT NULL DEFAULT '1' COMMENT '1男 2女 0未知',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '邮箱',
  `avatar` varchar(255) DEFAULT NULL COMMENT '头像访问路径，如 /uploads/avatar/xxx.jpg',
  `openid` varchar(64) DEFAULT NULL COMMENT '微信小程序 openid',
  `balance_fen` bigint NOT NULL DEFAULT '0' COMMENT '账户余额（单位：分）',
  `doctor_id` bigint DEFAULT NULL COMMENT '医生角色绑定的 doctor.id',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：0禁用 1启用',
  `role` varchar(30) NOT NULL DEFAULT 'USER' COMMENT '角色编码，对应 sys_role.code',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `create_user` int DEFAULT NULL COMMENT '创建者的id',
  `update_user` int DEFAULT NULL COMMENT '最后更新者的id',
  `username_active` varchar(50) GENERATED ALWAYS AS (if((`deleted` = 0),`username`,NULL)) VIRTUAL,
  `openid_active` varchar(64) GENERATED ALWAYS AS (if((`deleted` = 0),`openid`,NULL)) VIRTUAL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username_active` (`username_active`),
  UNIQUE KEY `uk_openid_active` (`openid_active`)
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户表';

