-- 导出  表 hospital_booking.user_favorite_doctor 结构
CREATE TABLE IF NOT EXISTS `user_favorite_doctor` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `doctor_id` bigint NOT NULL COMMENT '医生id',
  `create_time` datetime NOT NULL DEFAULT (now()) COMMENT '创建时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `user_doctor_active` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS (if((`deleted` = 0),concat(`user_id`,_utf8mb4':',`doctor_id`),NULL)) VIRTUAL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_doctor_active` (`user_doctor_active`),
  KEY `idx_ufd_user` (`user_id`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户收藏医生表';

